reports:"\u0645\u0627\u06C1\u0627\u0646\u06C1 \u06A9\u0644\u0648\u0632\u0646\u06AF \u0631\u067E\u0648\u0631\u0679",drawer_analytics:"\u0639\u0644\u0627\u0642\u0627\u0626\u06CC \u062A\u062C\u0632\u06CC\u06C1 (Area)",drawer_inventory:"\u0627\u0633\u0679\u0627\u06A9 \u0627\u0648\u0631 \u0633\u0627\u0645\u0627\u0646 (\u062A\u0627\u0631\u060C \u0631\u0627\u0624\u0679\u0631)",drawer_expenses:"\u0631\u0648\u0632\u0645\u0631\u06C1 \u06A9\u06D2 \u0627\u062E\u0631\u0627\u062C\u0627\u062A",drawer_field_tools:"\u0641\u06CC\u0644\u0688 \u0679\u0648\u0644\u0632\u2026",drawer_assistant:"\u0645\u0627\u0644\u06A9 \u06A9\u0627 \u0688\u06CC\u062C\u06CC\u0679\u0644 \u0627\u0633\u0633\u0679\u0646\u0679",drawer_alerts:"\u0627\u06C1\u0645 \u0627\u0644\u0631\u0679\u0633 \u0648 \u0627\u0644\u0631\u0679 \u0633\u0633\u0679\u0645",drawer_recovery:"\u0628\u0642\u0627\u06CC\u0627 \u062C\u0627\u062A \u06A9\u06CC \u0631\u06CC\u06A9\u0648\u0631\u06CC",drawer_quick_collect:"\u0641\u0648\u0631\u06CC \u0646\u0642\u062F \u0648\u0635\u0648\u0644\u06CC",drawer_search:"\u0641\u0648\u0631\u06CC \u0635\u0627\u0631\u0641 \u062A\u0644\u0627\u0634",drawer_rounds:"\u0641\u06CC\u0644\u0688 \u0648\u0635\u0648\u0644\u06CC \u06A9\u0627 \u0631\u0648\u0679",drawer_settings:"\u0627\u06CC\u067E \u0633\u06CC\u0679\u0646\u06AF\u0632",drawer_backup:"\u0628\u06CC\u06A9 \u0627\u067E \u0627\u0648\u0631 \u0628\u062D\u0627\u0644\u06CC",drawer_collapse:"\u0633\u0627\u0626\u06CC\u0688 \u0628\u0627\u0631 \u0628\u0646\u062F \u06A9\u0631\u06CC\u06BA",drawer_close:"\u0645\u06CC\u0646\u0648 \u0628\u0646\u062F \u06A9\u0631\u06CC\u06BA",more_menu_title:"\u0645\u0632\u06CC\u062F \u0641\u06CC\u0686\u0631\u0632 \u0627\u0648\u0631 \u06A9\u0627\u0631\u0648\u0628\u0627\u0631\u06CC \u0679\u0648\u0644\u0632",more_language_toggle:"\u{1F310} \u0632\u0628\u0627\u0646: English / \u0627\u0631\u062F\u0648",more_menu_group_billing:"\u0628\u0644\u0646\u06AF \u0627\u0648\u0631 \u06A9\u0627\u0631\u0648\u0628\u0627\u0631\u06CC \u0627\u0645\u0648\u0631",m